// some dependencies among options

#ifdef NDEBUG
#define TRN_ASSERT(ex)
#else
[[noreturn]]
void report_assertion(const char *expr, const char *file, unsigned int line);
#define TRN_ASSERT(expr_)                                 \
    do                                                    \
    {                                                     \
        if (!(expr_))                                     \
        {                                                 \
            report_assertion(#expr_, __FILE__, __LINE__); \
        }                                                 \
    } while (false)
#endif

