// miscellanea

inline const char *plural(int num)
{
    return num == 1 ? "" : "s";
}

template <typename T, typename U>
bool all_bits(T val, U bits)
{
    const T tbits = static_cast<T>(bits);
    return (val & tbits) == tbits;
}

